text:
それぞれの井戸周辺の死亡者数を計算


# 「周辺」を半径100m以内と定義
radius &lt;- 100

# 各井戸と各死亡地点の組み合わせを作る
pump_case_distance &lt;- tidyr::crossing(
  pump_locations |&gt;
    transmute(
      pump_id = id,
      pump_e = Easting,
      pump_n = Northing
    ),
  cholera_cases |&gt;
    transmute(
      case_id = id,
      Count,
      case_e = Easting,
      case_n = Northing
    )
) |&gt;
  # 各井戸から各死亡地点までの距離を計算
  mutate(
    distance = sqrt(
      (case_e - pump_e)^2 +
      (case_n - pump_n)^2
    )
  )

それぞれの井戸周辺の死亡者数を計算


## 井戸ごとに半径100m以内の死亡者数を集計 ##
pump_deaths &lt;- pump_case_distance |&gt;
  group_by(pump_id, pump_e, pump_n) |&gt;
  summarise(
    deaths_nearby = sum(Count[distance &lt;= radius]),
    .groups = "drop"
  ) |&gt;
  # 周辺死亡者数が多い順に並べる
  arrange(desc(deaths_nearby))

pump_deaths

疑わしい井戸を選ぶ

周辺の死者数が最も多い二つの井戸を取り出す

## 周辺の死者数が最も多い二つの井戸を取り出す ##
top2_pumps &lt;- pump_deaths |&gt;
  slice_max(
    deaths_nearby,
    n = 2,
    with_ties = FALSE
  ) |&gt;
  arrange(desc(deaths_nearby)) |&gt;
  transmute(
    id = pump_id,
    Easting = pump_e,
    Northing = pump_n,
    deaths_nearby
  )
